def get_total_number_of_sequences(n: int, max_element: int) -> int:
    # dp[i][x]: number of sequences of length i starting with element x
    # We want total sequences of length n, with first element in [1..max_element],
    # and each next element >= 2 * previous element.

    # Base case: for i=1, dp[1][x] = 1 for all x in [1..max_element]
    dp = [0] * (max_element + 1)
    for x in range(1, max_element + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (max_element + 1)
        # To compute new_dp[x], sum dp[y] for all y >= 2*x
        # So for each x, sum dp[y] for y in [2*x..max_element]
        # Precompute suffix sums of dp for efficient queries
        suffix_sum = [0] * (max_element + 2)
        for i in range(max_element, 0, -1):
            suffix_sum[i] = suffix_sum[i + 1] + dp[i]

        for x in range(1, max_element + 1):
            if 2 * x <= max_element:
                new_dp[x] = suffix_sum[2 * x]
            else:
                new_dp[x] = 0

        dp = new_dp

    return sum(dp[1:max_element + 1])

