def find_solution(a, b, n):
    # We want to find integers x, y such that a*x + b*y = n
    # with x >= 0.
    # If no solution exists, return "No solution".

    # Special case when both a and b are zero
    if a == 0 and b == 0:
        return ('x = ', 0, ', y = ', 0) if n == 0 else "No solution"

    # If a == 0, then b*y = n -> y = n/b if divisible and x=0
    if a == 0:
        if b != 0 and n % b == 0:
            y = n // b
            if y >= 0:
                return ('x = ', 0, ', y = ', y)
        return "No solution"

    # If b == 0, then a*x = n -> x = n/a if divisible and x>=0
    if b == 0:
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return ('x = ', x, ', y = ', 0)
        return "No solution"

    # General case:
    # Use Extended Euclidean Algorithm to find one solution to a*x + b*y = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (gcd, x, y)

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return "No solution"

    # Scale the solution to get one solution for a*x + b*y = n
    x0 *= n // gcd
    y0 *= n // gcd

    # Adjust sign if a or b are negative
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # Now general solution is:
    # x = x0 + k * (b/gcd)
    # y = y0 - k * (a/gcd)
    # We want x >= 0 and integers

    step_x = b // gcd
    step_y = a // gcd

    # Find k such that x >= 0:
    # x0 + k*step_x >= 0  =>  k >= -x0/step_x (if step_x > 0)
    # or k <= -x0/step_x (if step_x < 0)
    # We want the smallest non-negative x, so we pick k accordingly.

    if step_x != 0:
        if step_x > 0:
            k = (-x0 + step_x - 1) // step_x  # ceil division for k
        else:
            k = (-x0) // step_x  # floor division for k
    else:
        # step_x == 0 means b == 0, handled before, so no step_x == 0 here
        k = 0

    # It's possible that k is negative, try k and k+1 to find valid non-negative x
    candidates = [k]
    if k > 0:
        candidates.append(k-1)
    candidates.append(k+1)

    for kk in candidates:
        x = x0 + kk * step_x
        y = y0 - kk * step_y
        if x >= 0 and isinstance(x, int) and isinstance(y, int):
            return ('x = ', x, ', y = ', y)

    return "No solution"

