def filter_data(data, predicate=None):
    """
    Filters measurements in a dictionary of people based on a predicate function or a threshold value.

    Parameters:
    - data: dict, where keys are person identifiers and values are measurements (numbers or collections).
    - predicate: function or number or None.
        If a function, it is called with each measurement and should return True/False.
        If a number, it is treated as a threshold: measurements greater than this number are kept.
        If None, all entries are kept.

    Returns:
    - dict containing only those people whose measurements satisfy the predicate/threshold.
    """
    if predicate is None:
        # no filtering
        return data.copy()
    elif callable(predicate):
        # predicate is a function
        return {person: measurement for person, measurement in data.items() if predicate(measurement)}
    else:
        # predicate is treated as a threshold number
        return {person: measurement for person, measurement in data.items() if measurement > predicate}

