def find_solution(a: int, b: int, n: int):
    # We want to find non-negative integers x,y such that:
    # a*x + b*y = n
    # If no such non-negative integer solution exists, return None.

    # Handle trivial cases
    if n < 0:
        return None
    if a == 0 and b == 0:
        return (0,0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    # Extended Euclid to find one integer solution (x0,y0) to a*x + b*y = gcd(a,b)
    def extended_gcd(p, q):
        if q == 0:
            return (p, 1, 0)
        g, x1, y1 = extended_gcd(q, p % q)
        x = y1
        y = x1 - (p // q) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None  # no solution at all

    # Scale the solution to n
    x0 *= n // g
    y0 *= n // g

    # General solution:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    # We want x >= 0 and y >= 0

    bg = b // g
    ag = a // g

    # Find k bounds for non-negative x and y
    # x >= 0 => x0 + k*bg >= 0 => k >= -x0/bg
    # y >= 0 => y0 - k*ag >= 0 => k <= y0/ag

    # Because k must be integer, we take ceiling/floor accordingly

    from math import ceil, floor

    k_min = ceil(-x0 / bg) if bg != 0 else float('-inf')
    k_max = floor(y0 / ag) if ag != 0 else float('inf')

    if k_min > k_max:
        return None  # no k satisfies both inequalities

    # Choose any k in [k_min, k_max], e.g., k = k_min
    k = k_min

    x = x0 + k * bg
    y = y0 - k * ag

    if x >= 0 and y >= 0:
        return (x, y)
    else:
        return None

