    max_depth = 1  # Current dictionary counts as depth 1

    for v in d.values():
        if isinstance(v, dict):
            max_depth = max(max_depth, 1 + dict_depth(v))
        elif isinstance(v, (list, tuple)):
            # Check nested structures inside the list/tuple to determine depth contribution
            max_sub_depth = 0
            for item in v:
                if isinstance(item, dict):
                    max_sub_depth = max(max_sub_depth, dict_depth(item))
                elif isinstance(item, (list, tuple)):
                    # recursively check nested lists/tuples
                    # but only if they contain dict or lists/tuples that contribute depth
                    nested_depth = dict_depth({0: item})  # wrap item in dict to reuse logic
                    max_sub_depth = max(max_sub_depth, nested_depth)
            if max_sub_depth > 0:
                max_depth = max(max_depth, 1 + max_sub_depth)

    return max_depth

