def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle single digit numbers directly
    if num < 9:
        return num + 1

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all digits are 9, next palindrome is 10...01 with length+1 digits
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    half = (length) // 2
    odd = length % 2 != 0

    # Construct the palindrome by mirroring the left half (and middle if odd)
    if odd:
        left = s[:half]
        middle = s[half]
        right = s[half+1:]
        palindrome = left + middle + left[::-1]
    else:
        left = s[:half]
        right = s[half:]
        palindrome = left + left[::-1]

    palindrome_num = int(palindrome)
    if palindrome_num > num:
        return palindrome_num

    # Need to increment the middle part and mirror again
    if odd:
        # Increment the middle digit plus left part as a number
        left_middle = s[:half+1]  # left + middle
        incremented = str(int(left_middle) + 1)
        # If length changed due to increment (e.g. 999 + 1 -> 1000)
        if len(incremented) > len(left_middle):
            # This means palindrome length increased by 1
            # So, palindrome is 1 + (len(s)-1 zeros) + 1
            return int('1' + ('0' * (length - 1)) + '1')
        new_left = incremented[:-1]
        new_middle = incremented[-1]
        palindrome = new_left + new_middle + new_left[::-1]
    else:
        left_num = int(left) + 1
        incremented = str(left_num)
        if len(incremented) > len(left):
            # Length increased, e.g., 99 -> 100
            # palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = incremented + incremented[::-1]

    return int(palindrome)

