def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of sequences of length i with last element x
    # For i=1, dp[1][x] = 1 for all x in [1..m]
    # For i>1, dp[i][x] = sum of dp[i-1][y] for all y where x >= 2*y and x <= m

    if n == 1:
        return m  # any element from 1 to m

    dp_prev = [1] * (m + 1)  # index 0 unused, dp_prev[x] for sequences length 1
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # To speed up summation, for each x, sum dp_prev[y] for y <= x//2
        # Precompute prefix sums of dp_prev
        prefix = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix[i] = prefix[i - 1] + dp_prev[i]

        for x in range(1, m + 1):
            max_y = x // 2
            if max_y >= 1:
                dp_curr[x] = prefix[max_y]
            # else dp_curr[x] = 0 by default

        dp_prev = dp_curr

    return sum(dp_prev[1:])

