def find_solution(a, b, n):
    # Using Extended Euclidean Algorithm to find integer solutions x, y for ax + by = n

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x1, y1 = extended_gcd(b, a % b)
            x = y1
            y = x1 - (a // b) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return None  # no integer solution

    # scale the solution
    x0 *= n // g
    y0 *= n // g

    # adjust signs if a or b were negative
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)

