def remove_column(data, key=None, index=None):
    """
    Recursively remove a specified key from all dictionaries and remove an element at a specified index
    from each inner list in nested list structures within the given data.

    Parameters:
    - data: The nested data structure (dict, list, or other).
    - key: The key to remove from dictionaries (if specified).
    - index: The index of elements to remove from inner lists (if specified).

    Returns:
    - A new data structure with the specified removals applied.
    """
    if isinstance(data, dict):
        # Remove the specified key if present
        new_dict = {}
        for k, v in data.items():
            if k != key:
                new_dict[k] = remove_column(v, key, index)
        return new_dict
    elif isinstance(data, list):
        new_list = []
        for item in data:
            if isinstance(item, list) and index is not None:
                # Remove element at index if valid
                if 0 <= index < len(item):
                    # Remove element at index and recursively process the rest
                    new_inner = item[:index] + item[index+1:]
                else:
                    new_inner = item[:]
                # Recursively apply remove_column on inner list elements
                new_list.append(remove_column(new_inner, key, index))
            else:
                # Recursively process each element
                new_list.append(remove_column(item, key, index))
        return new_list
    else:
        # For other data types, return as is
        return data

